function createStack() {
  const stack = { items: [] };
  stack.push = (x) => stack.items.push(x);
  stack.size = () => stack.items.length;
  return stack;
}

const s = createStack();
s.push(1);
s.push(2);
s.items?.push(99);
console.log(s.size(), s.items);

